"""Original synthetic causal-inference lessons. No external data are read.
All numerical case results come from the standalone generators below.
"""
import json, math, html, hashlib
from pathlib import Path
from course_common import render_lesson, table, bars, line_chart, write_lab, esc
ROOT=Path(__file__).resolve().parents[1]

def p(t): return '<p>'+t+'</p>'
def eq(t): return '<div class="formula" role="note">'+t+'</div>'
def sec(i,title,body,check='',answer=''):
    return dict(id=i,title=title,body=body,check=check,answer=p(answer) if answer else '')
def f(x,d=3): return f'{x:,.{d}f}'
def pct(x,d=2): return f'{100*x:.{d}f}%'
def dag(nodes,edges,title):
    """Simple hand-authored causal diagram with a textual edge list."""
    mid='arrow-'+hashlib.sha256(title.encode()).hexdigest()[:10]
    out='<figure><svg viewBox="0 0 720 260" role="img" aria-label="'+esc(title)+'"><title>'+esc(title)+'</title><defs><marker id="'+mid+'" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#276451"/></marker></defs>'
    for a,b in edges:
        x,y=nodes[a];xx,yy=nodes[b];dx=xx-x;dy=yy-y;length=(dx*dx+dy*dy)**.5; ux=dx/length;uy=dy/length
        out+=f'<line x1="{x+31*ux}" y1="{y+31*uy}" x2="{xx-34*ux}" y2="{yy-34*uy}" stroke="#276451" stroke-width="3" marker-end="url(#{mid})"/>'
    for name,(x,y) in nodes.items():out+=f'<circle cx="{x}" cy="{y}" r="30" fill="#eef3eb" stroke="#276451"/><text x="{x}" y="{y+5}" text-anchor="middle" font-size="19">{esc(name)}</text>'
    return out+'</svg><figcaption>'+esc(title)+'. Arrows: '+esc('; '.join(a+' → '+b for a,b in edges))+'.</figcaption></figure>'

LAB7=r'''"""Lesson 7. All data are invented, fixed-seed teaching observations.
DGPs are chosen for pedagogy, not estimated from any external dataset.
One ad observation is one independently assigned, fully followed user.
"""
import json,itertools,math
import numpy as np
from scipy.stats import norm
rng=np.random.default_rng(7107)
n=12
skill=rng.integers(0,4,n); load=rng.integers(0,3,n)
y0=40+4*skill-2*load+rng.normal(0,2,n)
tau=2+1.5*skill-2*load
y1=y0+tau
d=(skill>=2).astype(int); y=np.where(d,y1,y0)
ate=tau.mean();att=tau[d==1].mean();atu=tau[d==0].mean()
gap=y[d==1].mean()-y[d==0].mean()
base=y0[d==1].mean()-y0[d==0].mean()
mini_y0=rng.integers(20,36,4).astype(float);mini_tau=rng.integers(-2,8,4).astype(float)
rollouts=[]
for chosen in itertools.combinations(range(4),2):
    z=np.array([i in chosen for i in range(4)])
    observed=mini_y0+z*mini_tau
    rollouts.append({'treated':','.join(str(i+1) for i in chosen),'estimate':float(observed[z].mean()-observed[~z].mean()),'baseline_gap':float(mini_y0[z].mean()-mini_y0[~z].mean()),'att':float(mini_tau[z].mean())})
ads=[]
for z in (0,1):
    N=12000; click=rng.binomial(1,.065+.009*z,N); buy=click*rng.binomial(1,.10-.005*z,N)
    ads.append({'arm':z,'users':N,'clicks':int(click.sum()),'actions':int(buy.sum()),'click_rate':float(click.mean()),'action_rate':float(buy.mean()),'postclick_rate':float(buy.sum()/click.sum())})
def diff(key):
    a,b=ads;p0=a[key];p1=b[key];se=math.sqrt(p0*(1-p0)/a['users']+p1*(1-p1)/b['users']);delta=p1-p0
    return {'difference':delta,'se':se,'low':delta-1.96*se,'high':delta+1.96*se,'relative':delta/p0,'p_value':float(2*norm.sf(abs(delta/se)))}
click_diff=diff('click_rate');action_diff=diff('action_rate')
z=rng.binomial(1,.5,3000);uptake_u=rng.uniform(size=len(z));take0=(uptake_u<.15).astype(int);take1=(uptake_u<.70).astype(int);take=np.where(z,take1,take0); outcome=20+4*take+rng.normal(0,4,len(z))
assert np.all(take1>=take0)
itt=outcome[z==1].mean()-outcome[z==0].mean();first=take[z==1].mean()-take[z==0].mean()
pbar=(.065+.073)/2;needed=math.ceil(2*(norm.ppf(.975)+norm.ppf(.8))**2*pbar*(1-pbar)/.008**2)
net={'value_per_action':30,'incremental_cost_per_user':.02,'per_user':30*action_diff['difference']-.02,'low':30*action_diff['low']-.02,'high':30*action_diff['high']-.02,'break_even_rate':.02/30}
out={'seed':7107,'teams':[{'team':i+1,'skill':int(skill[i]),'load':int(load[i]),'d':int(d[i]),'y0':float(y0[i]),'y1':float(y1[i]),'tau':float(tau[i]),'observed':float(y[i])} for i in range(n)],'ate':float(ate),'att':float(att),'atu':float(atu),'treated_share':float(d.mean()),'observed_gap':float(gap),'baseline_gap':float(base),'mini_y0':mini_y0.tolist(),'mini_tau':mini_tau.tolist(),'rollouts':rollouts,'randomization_mean':float(np.mean([r['estimate'] for r in rollouts])),'mini_ate':float(mini_tau.mean()),'ads':ads,'click_diff':click_diff,'action_diff':action_diff,'itt':float(itt),'first_stage':float(first),'wald':float(itt/first),'sample_size_per_arm':needed,'net':net}
assert np.isclose(gap,att+base)
assert np.isclose(ate,d.mean()*att+(1-d.mean())*atu)
assert np.isclose(out['randomization_mean'],out['mini_ate'])
print(json.dumps(out,indent=2,allow_nan=False))
'''

LAB8=r'''"""Lesson 8. Synthetic DAGs and conditional comparisons; seed 8108.
Independent exogenous Gaussian draws implement the displayed structural equations.
No parameter or observation is fitted to an external source.
"""
import json
import numpy as np
rng=np.random.default_rng(8108)
def ols(y,*xs):
    X=np.column_stack([np.ones(len(y))]+list(xs));b=np.linalg.lstsq(X,y,rcond=None)[0];res=y-X@b
    return {'coef':b.tolist(),'r2':float(1-res@res/((y-y.mean())@(y-y.mean())))}
n=900;s=rng.choice(3,n,p=[.5,.3,.2]);x=rng.normal(size=n);e=np.array([.2,.5,.8])[s];d=rng.binomial(1,e)
y0=10+5*s+2*x+rng.normal(0,2,n);tau=2+s;y=y0+d*tau
rows=[]
for k in range(3):
    a=(s==k)&(d==1);b=(s==k)&(d==0)
    rows.append({'stratum':k,'n':int((s==k).sum()),'treated':int(a.sum()),'control':int(b.sum()),'mean_t':float(y[a].mean()),'mean_c':float(y[b].mean()),'gap':float(y[a].mean()-y[b].mean()),'truth':float(2+k)})
weights={key:np.array([r[field] for r in rows],float) for key,field in [('ATE','n'),('ATT','treated'),('ATU','control')]}
standardized={key:float(w@np.array([r['gap'] for r in rows])/w.sum()) for key,w in weights.items()}
truth={'ATE':float(tau.mean()),'ATT':float(tau[d==1].mean()),'ATU':float(tau[d==0].mean())}
matched=[];distance=[];used=[]
for i in np.where(d==1)[0]:
    candidates=np.where((d==0)&(s==s[i]))[0];j=candidates[np.argmin(abs(x[candidates]-x[i]))]
    matched.append(y[i]-y[j]);distance.append(abs(x[i]-x[j]));used.append(int(j))
m=6000
X=rng.normal(size=m);D=.9*X+rng.normal(size=m);Y=-D+3*X+rng.normal(size=m)
conf={'naive':ols(Y,D),'adjusted':ols(Y,D,X),'population_naive':-1+3*.9/(.9**2+1),'truth':-1,'cov_ratio':float(np.cov(D,X,ddof=0)[0,1]/np.var(D))}
D=rng.normal(size=m);U=rng.normal(size=m);Y=.6*D+1.5*U+rng.normal(size=m);C=D+U+.3*rng.normal(size=m);R=C+.5*rng.normal(size=m)
coll={'naive':ols(Y,D),'adjusted':ols(Y,D,C),'descendant':ols(Y,D,R),'truth':.6,'population_adjusted':.6-1.5/(1+.3**2)}
D=rng.normal(size=m);M=.8*D+rng.normal(size=m);Y=.5*D+1.5*M+rng.normal(size=m)
med={'total':ols(Y,D),'direct':ols(Y,D,M),'truth_total':.5+.8*1.5,'truth_direct':.5}
print(json.dumps({'seed':8108,'n':n,'strata':rows,'standardized':standardized,'truth':truth,'raw_gap':float(y[d==1].mean()-y[d==0].mean()),'weights':{key:(w/w.sum()).tolist() for key,w in weights.items()},'matching':{'att':float(np.mean(matched)),'mean_distance':float(np.mean(distance)),'max_distance':float(np.max(distance)),'treated_n':len(matched),'unique_controls':len(set(used))},'confounding':conf,'collider':coll,'mediation':med},indent=2,allow_nan=False))
'''

LAB9=r'''"""Lesson 9. Synthetic process-coaching program at fictional facilities.
Seed 9109; no input files, network, external observations or empirical calibration.
X and B precede assignment. Selection is ignorable given them by construction.
"""
import json
import numpy as np
from scipy.special import expit
from sklearn.linear_model import LogisticRegression
rng=np.random.default_rng(9109);n=2400
x=rng.normal(size=n);b=rng.binomial(1,.45,n)
true_e=expit(-.3+1.2*x+.8*b)
d=rng.binomial(1,true_e)
y0=45+4*x+2*x*x+3*b+rng.normal(0,5,n)
tau=3+1.5*x+2*b;y=y0+d*tau

def fit_predict(interactions=True):
    def design(z):
        cols=[np.ones(n),z,x,x*x,b]
        if interactions:cols.extend([z*x,z*b])
        return np.column_stack(cols)
    X=design(d);beta=np.linalg.lstsq(X,y,rcond=None)[0]
    L=design(np.ones(n))-design(np.zeros(n));contrast=L@beta
    bread=np.linalg.inv(X.T@X);h=np.einsum('ij,jk,ik->i',X,bread,X);res=y-X@beta;cov=bread@(X.T@((res/(1-h))[:,None]**2*X))@bread
    avgL=L.mean(axis=0);se=float(np.sqrt(avgL@cov@avgL))
    return {'ate_se':se,'ate_low':float(contrast.mean()-1.96*se),'ate_high':float(contrast.mean()+1.96*se),'beta':beta.tolist(),'ate':float(contrast.mean()),'att':float(contrast[d==1].mean()),'atu':float(contrast[d==0].mean()),'subgroup_b0':float(contrast[b==0].mean()),'subgroup_b1':float(contrast[b==1].mean())}
full=fit_predict();additive=fit_predict(False)
# Estimated score has an intercept, X, and B, matching the assignment form.
ps=LogisticRegression(C=1e6,max_iter=2000).fit(np.column_stack([x,b]),d).predict_proba(np.column_stack([x,b]))[:,1]
w=np.where(d,1/ps,1/(1-ps))
def wmean(v,z,weights): return float(np.average(v[d==z],weights=weights[d==z]))
def ess(a):return float(a.sum()**2/(a@a))
def smd(v,weights):
    # Fixed, unweighted pooled within-arm SD makes before/after comparable.
    scale=np.sqrt((v[d==1].var(ddof=1)+v[d==0].var(ddof=1))/2)
    return (wmean(v,1,weights)-wmean(v,0,weights))/scale
balance=[{'variable':name,'before':float(smd(v,np.ones(n))),'ipw':float(smd(v,w))} for name,v in [('workload X',x),('baseline B',b),('workload squared',x*x)]]
ipw=wmean(y,1,w)-wmean(y,0,w)
# ATT coarsened exact matching. Each retained treated unit gets weight 1;
# each control in its cell gets n_t(cell)/n_c(cell).
cells=np.digitize(x,[-1.5,-.75,0,.75,1.5])*2+b
cw=np.zeros(n);cell_rows=[]
for c in np.unique(cells):
    mask=cells==c;nt=int((mask&(d==1)).sum());nc=int((mask&(d==0)).sum());keep=nt>0 and nc>0
    if keep:cw[mask&(d==1)]=1;cw[mask&(d==0)]=nt/nc
    cell_rows.append({'cell':int(c),'treated':nt,'control':nc,'retained':bool(keep)})
keep=cw>0;cem=wmean(y,1,cw)-wmean(y,0,cw)
for r,v in zip(balance,[x,b,x*x]):r['cem']=float(smd(v,cw))
bins=np.linspace(0,1,11);hist=[]
for a,z in [('Control',0),('Treated',1)]:hist.append(np.histogram(ps[d==z],bins=bins)[0].tolist())
# A harder assignment scenario illustrates failed overlap, not merely poor fitting.
hard=(x>.5).astype(int);no_support=int((hard==1).sum())
# A sample-rule audit uses artificial eligibility labels, never private firm data.
age=rng.integers(1,16,n);region=rng.choice(['North','South','East'],n)
eligible=(age>=3)&np.isin(region,['North','South'])
wrong=(age>=3)|np.isin(region,['North','South'])
# Omitted variable sensitivity is a separate DGP with a newly drawn latent cause.
u=rng.normal(size=n);dh=rng.binomial(1,expit(-.3+.8*x+.8*b+u));yh=45+4*x+3*b+2*u+3*dh+rng.normal(0,5,n)
Xh=np.column_stack([np.ones(n),dh,x,b]);hidden_coef=float(np.linalg.lstsq(Xh,yh,rcond=None)[0][1])
# Conditional effect function transported to an explicitly different synthetic target.
xt=rng.normal(.7,1,2000);bt=rng.binomial(1,.7,2000);target_truth=float((3+1.5*xt+2*bt).mean())
beta=np.array(full['beta']);transport=float((beta[1]+beta[5]*xt+beta[6]*bt).mean())
out={'seed':9109,'n':n,'treated':int(d.sum()),'control':int((1-d).sum()),'means':{'treated':float(y[d==1].mean()),'control':float(y[d==0].mean())},'raw_gap':float(y[d==1].mean()-y[d==0].mean()),'truth':{'ate':float(tau.mean()),'att':float(tau[d==1].mean()),'atu':float(tau[d==0].mean())},'regression':full,'additive':additive,'ipw':float(ipw),'cem':float(cem),'cem_truth_att':float(tau[(d==1)&keep].mean()),'cem_kept_treated':int(((d==1)&keep).sum()),'cem_kept_control':int(((d==0)&keep).sum()),'cells':cell_rows,'balance':balance,'scores':{'min':float(ps.min()),'max':float(ps.max()),'tail_n':int(((ps<.05)|(ps>.95)).sum()),'hist_centers':((bins[:-1]+bins[1:])/2).tolist(),'control_hist':hist[0],'treated_hist':hist[1]},'weights':{'max':float(w.max()),'ess_t':ess(w[d==1]),'ess_c':ess(w[d==0])},'hard_assignment_treated_without_controls':no_support,'audit':{'correct_n':int(eligible.sum()),'wrong_n':int(wrong.sum()),'extra_n':int((wrong&~eligible).sum())},'hidden_cause':{'true_effect':3,'adjusted_omitting_u':hidden_coef},'transport':{'true_target':target_truth,'estimated_target':transport}}
assert out['audit']['wrong_n']-out['audit']['correct_n']==out['audit']['extra_n']
print(json.dumps(out,indent=2,allow_nan=False))
'''

LAB10=r'''"""Lesson 10. Synthetic facility rollout panel, fixed seed 10110.
80 facilities, 8 periods, fixed baseline treatment groups, rollout at period 4.
Unit heterogeneity, common shocks and AR(1) noise generate repeated observations.
No external sources or empirical calibration. All units remain observed.
"""
import json
import numpy as np
from scipy.stats import t as student_t
rng=np.random.default_rng(10110);G=80;T=8
# Purposive adoption depends on baseline type, but the untreated DGP has common trends.
x=rng.normal(size=G);treated=(x+ .6*rng.normal(size=G)>0).astype(int)
size=rng.integers(50,201,G);alpha=55+5*x+rng.normal(0,3,G);tau=2+1.2*x
noise=np.zeros((G,T));noise[:,0]=rng.normal(0,2,G)
for t in range(1,T):noise[:,t]=.65*noise[:,t-1]+rng.normal(0,1.5,G)
common=np.array([0,.5,.9,1.4,2.0,2.4,2.8,3.5])
y0=alpha[:,None]+common+noise
y=y0+treated[:,None]*(np.arange(T)>=4)*tau[:,None]
pre=y[:,:4].mean(1);post=y[:,4:].mean(1);delta=post-pre
means={'treated_pre':float(pre[treated==1].mean()),'treated_post':float(post[treated==1].mean()),'control_pre':float(pre[treated==0].mean()),'control_post':float(post[treated==0].mean())}
did=means['treated_post']-means['treated_pre']-means['control_post']+means['control_pre']
N=G*T;g=np.repeat(np.arange(G),T);d=np.repeat(treated,T);postrow=np.tile(np.arange(T)>=4,G).astype(int)
X=np.column_stack([np.ones(N),d,postrow,d*postrow]);outcome=y.ravel();beta=np.linalg.lstsq(X,outcome,rcond=None)[0];res=outcome-X@beta;bread=np.linalg.inv(X.T@X)
naive_cov=(res@res/(N-X.shape[1]))*bread
meat=np.zeros((4,4))
for k in range(G):
    score=X[g==k].T@res[g==k];meat+=np.outer(score,score)
cluster_cov=G/(G-1)*(N-1)/(N-X.shape[1])*bread@meat@bread
cluster_se=float(np.sqrt(cluster_cov[3,3]));crit=float(student_t.ppf(.975,G-1))
naive_se=float(np.sqrt(naive_cov[3,3]))
prechange=y[:,3]-y[:,0];early=float(prechange[treated==1].mean()-prechange[treated==0].mean());earlyse=float(np.sqrt(prechange[treated==1].var(ddof=1)/(treated==1).sum()+prechange[treated==0].var(ddof=1)/(treated==0).sum()))
vt=prechange[treated==1].var(ddof=1)/(treated==1).sum();vc=prechange[treated==0].var(ddof=1)/(treated==0).sum();earlydf=float((vt+vc)**2/(vt**2/((treated==1).sum()-1)+vc**2/((treated==0).sum()-1)));earlycrit=float(student_t.ppf(.975,earlydf))
weighted=float(np.average(delta[treated==1],weights=size[treated==1])-np.average(delta[treated==0],weights=size[treated==0]))
weighted_truth=float(np.average(tau[treated==1],weights=size[treated==1]))
# Counterfactual violations: add a treated-only untreated drift after baseline,
# or give comparison facilities part of the same post-rollout effect.
def estimator(a):
    change=a[:,4:].mean(1)-a[:,:4].mean(1)
    return float(change[treated==1].mean()-change[treated==0].mean())
drift=.35*treated[:,None]*np.arange(T)
spill=.8*(1-treated[:,None])*(np.arange(T)>=4)
anticipation=1.2*treated[:,None]*(np.arange(T)==3)
# Changing sample composition: remove low-baseline treated facilities post-period.
retained=(treated==0)|(alpha>=np.median(alpha[treated==1]))
composition=float(post[(treated==1)&retained].mean()-pre[treated==1].mean()-(post[treated==0].mean()-pre[treated==0].mean()))
# Log specification is a genuinely different transformed outcome model.
logdid=estimator(np.log(y));logchange=np.log(y[:,4:].mean(1))-np.log(y[:,:4].mean(1));logratio=float(logchange[treated==1].mean()-logchange[treated==0].mean())
series={'Treated observed':y[treated==1].mean(0).tolist(),'Comparison observed':y[treated==0].mean(0).tolist(),'Treated untreated truth':y0[treated==1].mean(0).tolist()}
# Baseline-weighted aggregate rates illustrate compatible numerators/denominators.
rate_before=float((pre*size).sum()/size.sum());unweighted_before=float(pre.mean())
out={'seed':10110,'units':G,'periods':T,'treated_units':int(treated.sum()),'control_units':int((1-treated).sum()),'rows':N,'means':means,'treated_change':means['treated_post']-means['treated_pre'],'control_change':means['control_post']-means['control_pre'],'counterfactual':means['treated_pre']+means['control_post']-means['control_pre'],'did':did,'truth_att':float(tau[treated==1].mean()),'regression_beta':beta.tolist(),'naive_se':naive_se,'cluster_se':cluster_se,'interval':[did-crit*cluster_se,did+crit*cluster_se],'pretrend':{'difference':early,'se':earlyse,'low':early-earlycrit*earlyse,'high':early+earlycrit*earlyse,'df':earlydf,'p_value':float(2*student_t.sf(abs(early/earlyse),earlydf))},'weighted_did':weighted,'weighted_truth_att':weighted_truth,'series':series,'violations':{'differential_drift':estimator(y+drift),'drift_bias':.35*(np.arange(4,8).mean()-np.arange(4).mean()),'comparison_spillover':estimator(y+spill),'anticipation':estimator(y+anticipation),'composition':composition,'post_treated_retained':int(((treated==1)&retained).sum())},'sensitivity':{'drifts':[-.5,-.25,0,.25,.5],'effects':[did-v for v in [-.5,-.25,0,.25,.5]]},'log_did':logdid,'log_percent':float(100*np.expm1(logdid)),'log_of_period_means_did':logratio,'baseline_weighted_rate':rate_before,'baseline_unweighted_rate':unweighted_before,'subgroups':[{'type':name,'n':int(((treated==1)&mask).sum()),'true_att':float(tau[(treated==1)&mask].mean())} for name,mask in [('X below 1',x<1),('X at least 1',x>=1)]]}
assert np.isclose(did,beta[3])
assert np.isclose(estimator(y),did)
assert np.all(y>0)
print(json.dumps(out,indent=2,allow_nan=False))
'''

def lesson7(r):
    a,b=r['ads'];click=r['click_diff'];act=r['action_diff'];row=r['teams'][0];net=r['net']
    teams=table(['Team','Skill','Load','D','Y(0)','Y(1)','Effect','Observed'],[[v['team'],v['skill'],v['load'],v['d'],f(v['y0'],2),f(v['y1'],2),f(v['tau'],2),f(v['observed'],2)] for v in r['teams']],'Fictional team potential outcomes; both worlds are visible only because we generated them')
    sections=[
    sec('causal-question','Will changing the action change the outcome?',p('A forecasting model asks which teams will finish more work. A causal question asks how the same teams would perform under a specified alternative. Those questions need different comparisons. High-performing teams might adopt a tool more often even if the tool does nothing; a useful intervention might also be targeted at teams starting behind.')+p('This lesson moves from a fully visible synthetic world to a simulated advertising experiment where only assigned outcomes are observed. In both cases the object is a difference between interventions, not a label attached to a correlation.'),'A tool predicts performance well. Does that establish the value of deploying it?','No. Prediction can exploit selection, baseline ability, or consequences of treatment. Deployment requires a comparison of potential outcomes under the deployment policy.'),
    sec('generator','Open the teaching world before analyzing it',p('The lab uses NumPy seed 7107. It draws skill from {0,1,2,3}, load from {0,1,2}, and independent normal baseline noise with standard deviation 2. The units are fictional teams, and the outcome is an arbitrary weekly production index. Every parameter is an invented teaching assumption, not an empirical estimate.')+eq('Yᵢ(0) = 40 + 4 skillᵢ − 2 loadᵢ + εᵢ; τᵢ = 2 + 1.5 skillᵢ − 2 loadᵢ; Yᵢ(1) = Yᵢ(0) + τᵢ.')+p('The initial adoption rule is D = 1 when skill is at least 2. This deliberate selection creates a visible distinction between treatment effects and baseline differences. Download the script to change the rule while keeping the potential outcomes fixed.')),
    sec('define-intervention','Make “adopt the tool” operational',p('Define treatment as enabling one specified scheduling tool, with the same onboarding and support, for one week. Define control as retaining the existing process over that week. Keep eligibility, outcome measurement and the follow-up window common to both groups. If onboarding changes too, the treatment is the package, not the software alone.')+p('A precise treatment does not hold every consequence fixed. If the tool changes coordination time and that changes production, coordination is part of the total effect. Adjusting for it would change the question.'),'Would comparing enthusiastic adopters with teams never offered the tool estimate the offer effect?','Not automatically. Adoption reflects behavior after an offer, while assignment to an offer is a different intervention. Define which policy is being evaluated before estimating it.'),
    sec('potential-outcomes','One team has two alternative outcomes',teams+p('The table reveals counterfactuals solely to teach the logic. In a real experiment each team experiences one intervention. The treatment effect is Y(1) − Y(0), not the observed outcome minus a forecast chosen after seeing the data.')),
    sec('switching','Use the switching equation in the right direction',eq('Yᵢ = DᵢYᵢ(1) + (1 − Dᵢ)Yᵢ(0).')+p(f"For team {row['team']}, D = {row['d']}, so its observed value is {f(row['observed'],2)}. Its other potential outcome is not observed by that assignment. The equation selects an outcome; it does not recover the missing one.")+p('A before–after measurement is a different time point, not the same team’s untreated outcome at the post-treatment date. Secular demand, learning and changing staffing can move outcomes even without adoption.'),'If D = 0, is the individual treatment effect zero?','No. D = 0 tells us which potential outcome is observed. It says nothing about the unobserved difference Y(1) − Y(0).'),
    sec('identification','Missing by design is not missing at random in a spreadsheet',p('Random assignment can identify an average effect without identifying any individual effect. The missingness is fundamental: the same unit cannot simultaneously receive both treatment versions at the same time. Filling in a missing counterfactual from a similar team is an estimator with assumptions, not a recovered observation.')+p('Separate identification from estimation. Identification asks whether the distribution of observed data plus defended assumptions determines the target. Estimation asks how to approximate that target from a finite sample. A very precise estimator cannot repair an unidentified contrast.')),
    sec('heterogeneity','High outcomes and large effects are different',bars([str(t['team']) for t in r['teams']],[t['tau'] for t in r['teams']],'Team-level treatment effects in the synthetic world','Production-index points')+p('The generated effect varies with both skill and load. A high baseline outcome need not imply a high gain. Likewise, an average near zero could conceal beneficial and harmful individual changes. Heterogeneity should be defined in the effect, not inferred from variation in treated outcomes alone.'),'Which quantity would rank teams by benefit if both potential outcomes were known?','Rank Y(1) − Y(0), not Y(1). In observational practice those individual differences are unavailable, so policy targeting needs additional modeling, validation and uncertainty.'),
    sec('estimands','ATE, ATT and ATU are different population choices',eq('ATE = E[Y(1) − Y(0)]; ATT = E[Y(1) − Y(0) | D = 1]; ATU = E[Y(1) − Y(0) | D = 0].')+table(['Target','Synthetic truth'],[['ATE',f(r['ate'])],['ATT',f(r['att'])],['ATU',f(r['atu'])]],'Three finite-population average effects')+p(f"With treated share p = {f(r['treated_share'])}, ATE = p × ATT + (1 − p) × ATU = {f(r['ate'])}. ATT describes selected adopters. It does not automatically answer what would happen when extending the tool to current nonadopters."),'When can ATT equal ATE despite nonrandom adoption?','For example, if treatment effects are constant, or if selection is unrelated to effect heterogeneity. Equality of these targets does not itself remove baseline selection bias in the observed outcome gap.'),
    sec('observed-gap','Compute the observed gap before calling it causal',p(f"The observed treated-minus-untreated mean difference is {f(r['observed_gap'])} points. This is a correct descriptive contrast, but it compares different teams under different interventions. The synthetic ATE is {f(r['ate'])}; the gap need not estimate it.")+p('Keep subtraction direction explicit. A positive treated-minus-control difference means treated outcomes are higher, not necessarily that treatment raises outcomes. Changing the order changes the sign, not the underlying evidence.')),
    sec('decomposition','Separate recipients’ effect from baseline selection',eq('E[Y | D=1] − E[Y | D=0] = ATT + {E[Y(0) | D=1] − E[Y(0) | D=0]}.')+p(f"Here {f(r['observed_gap'])} = {f(r['att'])} + {f(r['baseline_gap'])}. The final term compares both groups under no treatment, not their observed pre-period levels. We can calculate it exactly only because the generator supplies both worlds.")+p('Bias must be stated relative to a target. Subtracting ATT from the raw gap leaves the baseline selection term. Subtracting ATE also brings in the difference between recipients’ effects and everyone’s effects.'),'If baseline selection is zero, does the observed difference necessarily equal ATE?','It equals ATT under consistency. To equal ATE as well, ATT must equal ATE, for example through full random assignment or effect homogeneity.'),
    sec('exchangeability','Comparability is an assignment claim',eq('(Y(0), Y(1)) ⟂ D  ⇒  E[Y | D=1] − E[Y | D=0] = ATE.')+p('Independence of assignment from both potential outcomes is stronger than equality of one baseline mean. Randomization provides a design-based reason for independence before outcomes are seen. Observational adjustment instead requires a credible argument that measured pre-treatment variables remove all common causes.')+p('An outside vendor, policy change or administrative rule is not automatically exogenous. Ask whether its timing and allocation depend on expected outcomes. The word “external” is not an identification proof.')),
    sec('assumptions','Keep versions, interference and overlap visible',p('<strong>Consistency:</strong> the observed outcome corresponds to the intervention specified. <strong>No interference:</strong> one team’s outcome is not changed by another team’s assignment. <strong>Positivity:</strong> each target type has a chance of receiving each intervention. These are separate from exchangeability.')+p('If tool users share recommendations with controls, the experiment may estimate a diluted assignment-policy effect. If all high-load teams must receive the tool, their untreated comparison is absent. Neither problem is fixed by a smaller regression p-value.'),'Would a random rule solve ambiguous treatment versions?','No. Randomization can balance assignment while the treatment itself remains ill-defined. Document the version, support, exposure and spillover boundary.'),
    sec('random-rule','Randomize assignment, not potential outcomes',p('Complete randomization selects a fixed number of treated teams uniformly from all allowable assignments. The teams and their potential outcomes remain fixed. Only the treatment labels move. Over assignments, the average treated baseline equals the average control baseline, even though any one rollout can be imbalanced.')+p('This is the key design-based distinction: unbiasedness is an average over hypothetical assignments, not a promise that one realized estimate equals the finite-population effect. Random sampling is a separate mechanism governing who enters the experiment.')),
    sec('enumeration','Enumerate all six two-of-four rollouts',table(['Treated team IDs','Observed gap','Recipients’ effect','Baseline gap'],[[v['treated'],f(v['estimate']),f(v['att']),f(v['baseline_gap'])] for v in r['rollouts']],'All assignments in a fresh four-team synthetic population')+p(f"The script constructs a separate four-team population, then assigns two teams in all six possible ways. The average estimate is {f(r['randomization_mean'])}, exactly the population ATE {f(r['mini_ate'])}. Individual assignment estimates differ because baseline imbalance and recipient composition vary.")+bars([v['treated'] for v in r['rollouts']],[v['estimate'] for v in r['rollouts']],'One experiment has many possible assignment results','Difference in outcome'),'Does choosing the assignment with the largest estimated effect preserve this argument?','No. Selecting after seeing outcomes changes the assignment or analysis mechanism and creates selection bias. Prespecified covariate-constrained randomization is different and requires inference matching that design.'),
    sec('audit-randomization','Evidence of randomization lives in the process',p('Retain the eligibility list, allocation code, random seed, assignment timestamps and exceptions log. Confirm that assignment occurred before exposure and that the implementation respected the recorded labels. Balance tables are useful diagnostics, but a nonsignificant balance test is not proof of randomization.')+p('Do not rerandomize until outcomes or p-values look favorable. If balance restrictions are part of the protocol, use baseline variables and specify them before treatment. Analyze all randomized units according to their original assignment unless a different estimand and valid identification strategy were prespecified.')),
    sec('unit','Choose a stable unit and analyze that design',p('An ad impression is not necessarily an independent experiment. The same person can appear many times, see both versions, or influence another person. Assign at the user, household, store or region level that fits the intervention, and measure outcomes over a common follow-up window.')+p('Clustering changes both the causal exposure and the effective information. Thousands of impressions within a few randomized regions do not create thousands of independent assignment units. Plan sample size using the assignment units and likely within-cluster correlation.'),'Why not randomize each page load when purchases are user-level?','Repeated users can cross treatments, carry exposure across sessions, and contribute dependent outcomes. Stable user assignment better defines the intervention and denominator for a user-level outcome.'),
    sec('noncompliance','Assignment and receipt can diverge',p(f"A separate encouragement simulation assigns offers at random and lets uptake depend on the offer. The observed first stage is {f(r['first_stage'])}; the intention-to-treat outcome effect is {f(r['itt'])}. Their ratio is {f(r['wald'])}.")+eq('Wald ratio = {E[Y | Z=1] − E[Y | Z=0]} / {E[D | Z=1] − E[D | Z=0]}.')+p('Under random encouragement, relevance, exclusion, monotonicity and suitable consistency/no-interference assumptions, this ratio identifies a complier average effect, not generally ATE. The generator’s receipt effect is 4 and offers have no direct effect, so those assumptions are built in here. In real work they need a substantive defense.'),'May we compare recipients with nonrecipients and call that randomized?','No. Receipt is not randomly assigned merely because the offer was. Intention-to-treat retains the random comparison; receipt-effect estimation needs additional assumptions.'),
    sec('ad-design','A new advertising experiment with explicit denominators',p('The next lab generates two independent arms of 12,000 fictional users. Each user receives only one ad version and complete follow-up. A click is Bernoulli with probability 0.065 + 0.009D. An action occurs only after a click, with conditional probability 0.10 − 0.005D. These probabilities are invented design inputs, not facts about advertising.')+table(['Arm','Assigned users','Clicks','Actions','Clicks/user','Actions/user'],[[v['arm'],v['users'],v['clicks'],v['actions'],pct(v['click_rate']),pct(v['action_rate'])] for v in r['ads']],'Fresh synthetic A/B outcomes')+p('The generated sample varies around these probabilities. Every estimate below is calculated from the simulated counts, not substituted from the generating expectations.')),
    sec('denominators','A rate answers the question in its denominator',p(f"Arm 0 has {pct(a['postclick_rate'])} actions per click; arm 1 has {pct(b['postclick_rate'])}. Those conditional rates describe selected clickers. If assignment changes who clicks, the clicker populations differ after treatment. They are not automatically a randomized comparison of conversion propensity.")+eq('Actions per assigned user = (clicks per assigned user) × (actions per click).')+p('Use actions per assigned user for an assignment-policy effect on actions. Report absolute percentage-point differences before relative lifts. A relative increase can look large when the baseline rate is small.'),'Can a version improve click rate but lower actions per click?','Yes. It may attract additional low-intent clickers. Neither metric alone determines the overall actions-per-user effect, which uses the original assigned denominator.'),
    sec('click-interval','Quantify uncertainty in the click contrast',eq('SE(p̂₁ − p̂₀) = √{p̂₁(1−p̂₁)/n₁ + p̂₀(1−p̂₀)/n₀}.')+p(f"The click difference is {f(100*click['difference'])} percentage points, or {pct(click['relative'])} relative to arm 0. Its approximate 95% unpooled normal interval is [{f(100*click['low'])}, {f(100*click['high'])}] percentage points. This calculation assumes independent users and the prespecified endpoint.")+bars(['Arm 0','Arm 1'],[100*a['click_rate'],100*b['click_rate']],'Click rates by assigned arm','Percent of assigned users')+p('For rare events or small arms, use an appropriate binomial or randomization-based interval rather than relying automatically on the normal approximation. Repeated peeking and many endpoint searches require a prespecified sequential or multiplicity strategy.')),
    sec('action-interval','Keep the downstream endpoint fixed',p(f"The action difference is {f(100*act['difference'])} percentage points. Its approximate 95% interval is [{f(100*act['low'])}, {f(100*act['high'])}] percentage points. A click result does not establish an action result, and failure to exclude zero does not establish equivalence.")+p('An equivalence claim needs a substantively meaningful margin and an interval or test designed around it. A decision can still be made under uncertainty, but it should distinguish evidence about the endpoint, estimated economic value, downside risk and the cost of waiting.'),'What should “no significant action difference” mean in a report?','The chosen test did not reject its null under its assumptions. Give the estimated difference and interval; do not translate that into proof of zero effect or equal versions.'),
    sec('binary-regression','With only a treatment indicator, the slope is the gap',eq('Yᵢ = α + βDᵢ + εᵢ; α̂ = mean(Y | D=0), β̂ = mean(Y | D=1) − mean(Y | D=0).')+p(f"For the binary action outcome, the intercept is {f(a['action_rate'],5)} and the slope is {f(act['difference'],5)}. OLS reproduces the difference in means exactly. The coefficient’s causal interpretation still comes from assignment and the estimand, not from calling the procedure regression.")+p('A Bernoulli outcome is heteroskedastic. Use appropriate robust, design-based or difference-in-proportions uncertainty. Covariate adjustment can improve precision when prespecified baseline covariates are available; a two-row summary does not contain those covariates.')),
    sec('decision','Translate effects into a decision threshold',p(f"In an explicitly hypothetical business scenario, each action contributes 30 currency units and the new version costs 0.02 extra per assigned user. The break-even effect is {f(100*net['break_even_rate'],3)} percentage points. Estimated incremental contribution is {f(net['per_user'],4)} per user, with the action interval translated to [{f(net['low'],4)}, {f(net['high'],4)}]. This ignores uncertainty in margins and costs.")+p(f"For a separate fixed-sample planning calculation, detecting an 0.8-percentage-point click difference near a 6.9% pooled rate with 80% power at two-sided 5% significance needs approximately {r['sample_size_per_arm']:,} users per arm. The simple normal approximation assumes independent observations and no multiplicity. Power for actions must use the action endpoint, not clicks."),'Why compare the interval with a break-even threshold rather than zero alone?','Zero is a scientific reference. The economic threshold includes incremental cost and value. A positive effect can still lose money, and a worthwhile decision can depend on risk and opportunity cost as well as statistical significance.'),
    sec('brief','Write a bounded causal decision brief',p('A defensible brief names the intervention, unit, eligible population, endpoint, follow-up period and estimand. It explains assignment and compliance, reports the effect with uncertainty, and distinguishes causal identification from transport to another setting. It states what could change the decision.')+p('For this fictional ad study, the assigned-user comparisons are randomized by construction and users are independent. That makes the simulated contrasts interpretable for the generated population. It supplies no empirical evidence that a real ad version will work. A real rollout would need implementation records, business inputs, uncertainty at the true assignment unit and an explicit follow-up plan.'),'What is the strongest transferable lesson from a synthetic experiment?','The reasoning and reproducible analysis workflow transfer. Its numerical effects do not. Design a real comparison whose assumptions and decision threshold can be defended.')
    ]
    assert len(sections)==24
    render_lesson(7,'From prediction to intervention','Define the causal target, separate selection from treatment, and design an experiment whose uncertainty matches the decision.',sections)
    return sections

def lesson8(r):
    co=r['confounding'];cl=r['collider'];me=r['mediation'];rows=r['strata'];m=r['matching']
    nodes={'D':(130,180),'Y':(590,180),'X':(360,50)}
    sections=[
    sec('conditional','Compare like with like, then name the target',p('An observational gap can mix a treatment contrast with differences in who receives treatment. Conditional comparison separates units into groups with common pre-treatment characteristics. The causal claim is not that adjustment makes the groups identical in every way, but that remaining assignment is independent of potential outcomes given those characteristics.')+eq('(Y(0),Y(1)) ⟂ D | S, together with consistency and 0 < P(D=1 | S=s) < 1.')+p('These assumptions identify conditional effects. To obtain a population average, integrate those effects over a stated target distribution. Different target weights can produce different valid effects.'),'What is missing if both treatments occur in every observed stratum?','Overlap makes comparison possible, but does not establish conditional exchangeability. An unmeasured common cause can remain within every stratum.'),
    sec('strata-generator','Generate a transparent observational population',p('Seed 8108 generates 900 fictional service teams. Baseline skill S takes values 0, 1, 2 with probabilities 0.5, 0.3, 0.2. Adoption probabilities are 0.2, 0.5, 0.8, so high-skill teams adopt more often. An independent baseline covariate X and independent outcome noise supply within-skill variation.')+eq('Y(0) = 10 + 5S + 2X + ε, with ε ∼ N(0, 2²); Y(1) − Y(0) = 2 + S.')+p('Because assignment depends only on S, conditioning on S suffices in this constructed world. That is known from the generator, not learned from a balance test. In real work the equivalent claim requires knowledge of the assignment process.')),
    sec('strata-calculation','Subclassification is a weighted calculation',table(['Skill','Total','Treated','Control','Treated mean','Control mean','Gap'],[[v['stratum'],v['n'],v['treated'],v['control'],f(v['mean_t']),f(v['mean_c']),f(v['gap'])] for v in rows],'Synthetic stratum counts and outcome contrasts')+eq('τ̂(w) = Σₛ wₛ {Ȳ₁ₛ − Ȳ₀ₛ}, where Σₛ wₛ = 1.')+p(f"The raw pooled gap is {f(r['raw_gap'])}. Standardizing to the sample’s skill composition gives {f(r['standardized']['ATE'])}. Check counts before percentages: a stratum with a tiny comparison group can dominate uncertainty even when its total population weight is modest."),'Why not weight each stratum equally?','Equal weighting describes a population with equal stratum shares. It is correct only if that is the target, not simply because three rows appear in the table.'),
    sec('target-weights','ATE, ATT and ATU keep the gaps but change the weights',table(['Target','Skill 0 weight','Skill 1 weight','Skill 2 weight','Estimate','Known truth'],[[key]+[f(v) for v in r['weights'][key]]+[f(r['standardized'][key]),f(r['truth'][key])] for key in ['ATE','ATT','ATU']],'Standardization to three explicitly different populations')+p('ATE weights use the full population’s skill shares. ATT weights use skill shares among recipients; ATU weights use shares among nonrecipients. The contrasts do not change, but the people represented by the weighted average do. Sampling error remains even with a correct adjustment set.'),'If recipients are concentrated in high-effect strata, which target tends to be larger?','ATT tends to exceed ATE and ATU, given that particular pattern. This ordering is substantive, not a universal algebraic property.'),
    sec('matching','A match supplies an estimate, not an observed counterfactual',p(f"The lab matches each treated team to a control of the same skill with nearest X, allowing replacement. It estimates ATT = {f(m['att'])} using {m['treated_n']} treated teams and {m['unique_controls']} distinct controls. The mean absolute X distance is {f(m['mean_distance'])}; the largest is {f(m['max_distance'])}.")+eq('For a treated focal unit: τ̂ᵢ = Yᵢ − Ymatched control. For an untreated focal unit: τ̂ᵢ = Ymatched treated − Yᵢ.')+p('Reuse is not harmless duplication. It changes dependence and effective information. Standard errors must account for the matching procedure and repeated controls; the sample standard deviation of pair differences divided by the square root of pairs is not automatically valid.')),
    sec('graph-language','Arrows encode causal commitments',dag(nodes,[('X','D'),('X','Y'),('D','Y')],'A common cause and a causal effect')+p('A directed acyclic graph represents qualitative causal structure. X is a parent of D and Y; D is a parent of Y. A descendant lies downstream along directed arrows. A path may be traversed against arrow direction when checking association; a directed causal path follows arrows all the way.')+p('An arrow does not specify linearity, sign, strength or time lag. Absence of an arrow is a substantive exclusion. A graph is a compact record of assumptions, not a certificate extracted automatically from correlations.')),
    sec('chain','A chain carries a mediated effect',dag({'D':(100,130),'M':(360,130),'Y':(620,130)},[('D','M'),('M','Y')],'The chain D → M → Y')+p('M is a noncollider on this path because the two arrows do not both point into M. Without conditioning, the path can transmit an association. Conditioning on M blocks this chain. If the target is the total effect of D, blocking a causal mechanism is usually the wrong adjustment.')+p('Examples include an offer changing attendance, which changes skill; or a process change reducing wait time, which changes satisfaction. The intermediate outcome is not a baseline confounder merely because it predicts the final outcome.'),'Does measuring M before Y make M a valid total-effect control?','No. It may still occur after D and carry part of D’s effect. Temporal ordering is necessary for the causal story but not sufficient for adjustment.'),
    sec('fork','A fork creates common-cause association',dag(nodes,[('X','D'),('X','Y')],'The fork D ← X → Y')+p('D and Y can be associated even with no D → Y arrow. X supplies common variation. Conditioning on X blocks the fork if the graph is adequate. The key is X’s causal role, not how much the coefficient moves after adding it.')+p('A baseline skill score can influence both adoption and performance. A statistical adjustment can remove measured skill differences, but it does not prove that the score captures every relevant aspect of skill, resources and motivation.')),
    sec('collider','A common consequence behaves differently',dag({'D':(110,70),'U':(610,70),'C':(360,190)},[('D','C'),('U','C')],'The collider D → C ← U')+p('C is a collider: both adjacent arrows point into it. The path is blocked unless we condition on C or a descendant of C. Among units with a fixed total C, more of one cause can imply less of the other. Selecting on an admission score, a completed survey or a diagnostic category can therefore induce association between otherwise independent causes.'),'Is selecting only complete responses a form of conditioning?','Yes. Sample restrictions condition on inclusion. If inclusion is a common consequence of treatment and outcome causes, complete-case analysis can open a noncausal path.'),
    sec('d-separation','Trace each path one internal node at a time',p('A path is blocked when an internal noncollider is conditioned on, or when it contains a collider with neither that collider nor a descendant conditioned on. A path is open only if every internal node passes its rule. D-separation means all paths between two nodes are blocked by the conditioning set.')+p('A node’s role belongs to the path. The same variable can be a collider on one path and a noncollider on another. Mark arrowheads along the specific path before deciding what conditioning does.'),'On D ← X → C ← U → Y, does conditioning on C make D and Y connected if X is also conditioned on?','No. Conditioning on C opens that collider, but conditioning on X blocks the same path at a noncollider. One blocker is sufficient for that path, though other paths must still be checked.'),
    sec('descendants','A collider’s descendant can open the path',dag({'D':(80,60),'U':(640,60),'C':(360,100),'R':(360,220)},[('D','C'),('U','C'),('C','R')],'Information about a collider can flow through a descendant')+p('Conditioning on R can reveal information about C and thereby associate C’s otherwise independent causes. A sample may be selected by a downstream review decision rather than by the collider itself. Trace the full inclusion process, not just the columns in the final regression.')+p('In the later simulation, R is a noisy measurement downstream of C. Its coefficient adjustment is less direct than conditioning on C, but it still opens the path. Noise may attenuate the problem; it does not guarantee its removal.')),
    sec('graph-evidence','Graphical implications are not automatic discoveries',p('Under the causal Markov assumption, d-separation implies conditional independence in the generated distribution. The converse needs additional assumptions such as faithfulness: different causal routes may cancel exactly, creating an independence not implied by the graph. Several DAGs can also encode the same observational independence structure.')+p('A zero regression coefficient is even narrower evidence. It can reflect a misspecified functional form, low power or a particular conditional mean relationship. Domain knowledge, timing and design restrictions remain necessary when choosing arrows.'),'If two variables are uncorrelated, must the graph omit every path between them?','No. Nonlinear dependence, cancellation and sampling uncertainty can all yield zero or near-zero correlation despite causal paths.'),
    sec('confounder-dgp','A common cause can reverse the observed slope',eq('X,u,ε independently ∼ N(0,1); D = 0.9X + u; Y = −D + 3X + ε.')+p('This separate simulation uses a continuous intervention D to make the linear algebra transparent. Increasing D by one unit while holding exogenous causes fixed reduces Y by one. However, high X raises both D and Y, creating positive selection.')+eq('Population naive slope = −1 + 3 Cov(D,X)/Var(D) = −1 + 3(0.9)/(0.9²+1).')+p(f"The resulting population naive slope is {f(co['population_naive'])}, even though the causal slope is −1. The omitted-variable term is about a common cause; it is not a universal reason to add all available predictors.")),
    sec('confounder-results','Adjustment recovers the constructed target',table(['Specification','Coefficient on D','R²'],[['Y on D',f(co['naive']['coef'][1]),f(co['naive']['r2'])],['Y on D and X',f(co['adjusted']['coef'][1]),f(co['adjusted']['r2'])]],'Fresh 6,000-observation confounder simulation')+bars(['Naive','Adjusted','True'],[co['naive']['coef'][1],co['adjusted']['coef'][1],co['truth']],'A common cause distorts the naive slope','Coefficient on D')+p('The adjusted coefficient is near the known −1 target because X is sufficient and the linear conditional model is correctly specified by construction. The code generates all disturbances and fits both models. A reversal in an unknown dataset would prompt a design audit, not establish that the second model is true.'),'What would a small p-value for the naive slope test?','A statistical coefficient under the fitted model and sampling assumptions. It does not test whether the slope equals the causal effect.'),
    sec('collider-dgp','Adding a predictive consequence can create bias',eq('D,U,ε independently ∼ N(0,1); Y = 0.6D + 1.5U + ε; C = D + U + 0.3v; R = C + 0.5w.')+p('D is unconfounded here. U affects Y, while D and U both affect the auxiliary score C. Conditioning on C makes D informative about U, opening D → C ← U → Y. Conditioning on R, C’s descendant, also opens that path. Neither variable is needed to identify the total D effect.')+p('The variables are synthetic continuous quantities. C is deliberately made predictive to show why outcome prediction and causal adjustment are different jobs. More explanatory power can accompany a worse effect estimate.')),
    sec('collider-results','A higher R² can accompany the wrong causal answer',table(['Model','D coefficient','R²'],[['No extra control',f(cl['naive']['coef'][1]),f(cl['naive']['r2'])],['Control C',f(cl['adjusted']['coef'][1]),f(cl['adjusted']['r2'])],['Control descendant R',f(cl['descendant']['coef'][1]),f(cl['descendant']['r2'])]],'Fresh collider and descendant simulation')+p(f"The true effect is {f(cl['truth'])}; the population coefficient after controlling C is {f(cl['population_adjusted'])}. The sign reversal is induced by adjustment. It does not reveal a negative causal effect.")+bars(['Unadjusted','With C','With R','True'],[cl['naive']['coef'][1],cl['adjusted']['coef'][1],cl['descendant']['coef'][1],cl['truth']],'Harmful adjustment in a known graph','Coefficient on D'),'Would increasing the sample size fix this control choice?','No. More data make the wrong population coefficient more precise. Identification bias can persist while sampling uncertainty vanishes.'),
    sec('backdoor','Block every backdoor path, not every path',p('A standard sufficient backdoor criterion for total-effect adjustment requires that the adjustment set contain no descendants of D and block every path from D to Y whose first edge points into D. The direct and mediated causal paths should remain available. This is a sufficient graphical criterion, not the only identification strategy.')+eq('E[Y(d)] = Σₓ E[Y | D=d, X=x] P(X=x), or the corresponding integral.')+p('Graphical sufficiency identifies the adjustment functional. It does not ensure that a chosen linear regression estimates that functional correctly. Functional form, overlap, measurement error and finite-sample uncertainty remain separate tasks.')),
    sec('mediator-estimand','Choose total or direct effect before fitting controls',eq('M = 0.8D + u; Y = 0.5D + 1.5M + ε; total effect = 0.5 + 0.8 × 1.5.')+p(f"The new mediation simulation estimates a total slope of {f(me['total']['coef'][1])} without M and a D slope of {f(me['direct']['coef'][1])} with M. The generating total effect is {f(me['truth_total'])}; the controlled direct effect is {f(me['truth_direct'])}.")+p('In this simple linear structural model the paths add. Real direct and indirect effects can require interventions on the mediator, no unmeasured mediator–outcome confounding, and care with treatment-induced confounders. Merely adding a mediator does not identify every mediation estimand.'),'Is the smaller adjusted D coefficient evidence the intervention matters less?','Not for the total-effect question. The model has intentionally removed a mechanism. A different estimand can be smaller without contradicting the total effect.'),
    sec('precision','Useful controls depend on what variation they remove',p('A prognostic pre-treatment variable can reduce residual outcome variance and improve precision. A variable that strongly predicts treatment but barely predicts outcome may leave little residual treatment variation and inflate uncertainty. With unmeasured confounding, some adjustment choices can even amplify bias.')+eq('Partial-regression slope = Cov(residualized D, residualized Y) / Var(residualized D).')+p('The numerator and denominator both change when adding controls. Evaluate the graph first, then precision and support. A treatment predictor is not universally forbidden, and a strong outcome predictor is not universally safe.')),
    sec('proxy','A noisy proxy does not automatically close a backdoor',p('Suppose an unobserved cause U affects D and Y, and W is a noisy measurement of U. Conditioning on W generally leaves residual variation in U that still confounds the comparison. A strong correlation between W and U is not exact conditioning on U.')+p('Contrast a true observed bottleneck: if every route from U into treatment passes through measured W, conditioning on W can block the backdoor under that graph. The distinction is structural, not a threshold correlation. Negative controls, validation data, instrumental designs or sensitivity analysis may help, but each adds its own assumptions.'),'Why is “we included a proxy for motivation” incomplete?','It does not establish that the proxy blocks all common-cause paths. State its measurement relation, what residual confounding may remain and how conclusions change under plausible residual bias.'),
    sec('overlap','Show the comparison population, not just an estimate',p('The synthetic skill strata all contain treated and control teams. That is observed support at the coarse skill level, not a guarantee that every fine combination of covariates has close matches. Matching distances help reveal where comparisons stretch.')+p(f"The least represented control cell in this realization has {min(v['control'] for v in rows)} teams. The largest nearest-match X distance is {f(m['max_distance'])}. These diagnostics belong next to the estimate. Trimming unsupported units can improve credibility but changes the target population."),'If unmatched treated units are dropped, can the result still be labeled the original ATT?','Only with additional assumptions or modeling for dropped recipients. Without them it is an effect for the retained, matchable treated population.'),
    sec('small-cells','Nonempty cells can still be fragile',p('A count above zero prevents an undefined sample mean, but it does not guarantee reliable inference. One unusual outcome can move a small cell substantially. Report cell sizes and uncertainty, and examine whether coarsening creates residual imbalance within cells.')+p('For independent samples and fixed stratum weights, a plug-in variance for a standardized gap is the sum of squared weights times the two within-cell mean variances. Estimated weights, clustering, repeated matching and sparse cells require additional care. A simple pooled standard error ignores the estimator’s structure.')+eq('Var(τ̂) ≈ Σₛ wₛ² {s²₁ₛ/n₁ₛ + s²₀ₛ/n₀ₛ}, for fixed weights and independent cells.')),
    sec('matching-direction','Check the sign before averaging matched differences',p('For ATT, each treated focal outcome is compared with an estimated untreated outcome. For ATU, each untreated focal outcome is subtracted from an estimated treated outcome. Reversing the order for untreated focal units incorrectly reverses the treatment effect.')+p('The reference population also determines weights. A control reused by many treated units contributes repeatedly to an ATT match. That is a consequence of the estimator, not evidence that many independent control outcomes were observed.'),'A control focal unit has observed Y(0), and its treated match has observed Y(1). Which subtraction estimates benefit?','Matched treated outcome minus focal untreated outcome. Always orient the difference as treatment minus no treatment, regardless of which unit is focal.'),
    sec('balance-not-proof','Balance is a diagnostic, not a causal certificate',p('After matching or weighting, compare measured baseline covariates under the analysis weights, including meaningful transformations and interactions. Good measured balance indicates that the procedure achieved part of its design objective. It cannot reveal a common cause never recorded.')+p('Avoid searching outcome models until a desired coefficient appears. Design the comparison using pre-treatment information, state the estimand, then analyze outcomes. This separation limits researcher discretion but does not erase substantive identification assumptions.')),
    sec('effect-shape','Identification does not specify a regression shape',p('Conditional exchangeability identifies a weighted conditional-mean contrast. A linear main-effects model imposes an additional structure: the effect is constant unless interactions are included, and continuous covariate associations follow the chosen functional form.')+p('Flexible models may reduce misspecification but can extrapolate badly where overlap is weak. Cross-fitting and doubly robust procedures can improve estimation under stated nuisance-model conditions; they do not repair unmeasured confounding or undefined interventions.'),'Why can a correct adjustment set coexist with a biased regression estimate?','The graph identifies which variables suffice, while the estimator may approximate the conditional means incorrectly or rely on unsupported extrapolation.'),
    sec('sensitivity','Ask which unsupported assumption could change the answer',p('A useful sensitivity analysis varies a specific vulnerability: residual common-cause bias, proxy error, overlap thresholds, cell boundaries or plausible effect heterogeneity. Explain how each variation maps to a change in the identifying argument or target.')+p('A collection of similar estimates is not a vote establishing truth. Models can share the same omitted cause. Conversely, different estimates may reflect different populations rather than instability. Keep the estimand and support constant before comparing methods.')),
    sec('exercise','Build an adjustment brief from the synthetic strata',p('Use the downloaded lab to change adoption probabilities while keeping the outcome generator intact. Predict the direction of the raw gap before running it. Then recompute ATE, ATT and ATU standardization weights. Next make one skill stratum always treated and identify the missing comparison rather than silently filling it in.')+p('For the DAG lab, increase collider measurement noise and examine the coefficient controlled for C. The bias should weaken as C becomes less informative about the common causes, but the exact sample result will fluctuate. Explain the population mechanism before interpreting a graph.'),'Does changing the fixed seed test the credibility of the causal assumptions?','It checks simulation variability and coding stability under the same assumptions. It does not validate those assumptions for a real population.'),
    sec('brief','Make the causal reasoning reviewable',p('A complete adjustment brief states the intervention and target, lists the temporal order of variables, draws the graph, identifies open backdoor paths and explains the chosen adjustment set. It gives overlap and balance diagnostics, calculation rules, uncertainty and sensitivity to unresolved causes.')+p(f"In this constructed service-team world, skill adjustment identifies an ATE estimated at {f(r['standardized']['ATE'])}, near its known generated value {f(r['truth']['ATE'])}. The result validates the calculation under the chosen DGP, not the applicability of that DGP to actual teams. The next lesson audits the implementation choices that often get hidden behind the word ‘adjusted’."),'What must travel with an adjusted effect estimate?','Its target population, treatment definition, adjustment rationale, observed support, estimator, uncertainty and remaining assumptions. A coefficient alone is not a causal argument.')
    ]
    assert len(sections)==28
    render_lesson(8,'Graphs, comparability and adjustment','Trace causal paths, choose what to condition on, and see confounders and colliders produce opposite adjustment lessons.',sections)
    return sections

def lesson9(r):
    reg=r['regression'];scores=r['scores'];w=r['weights'];audit=r['audit'];h=r['hidden_cause']
    sections=[
    sec('target-trial','Start with the trial you wish you could run',p('The fictional decision is whether to offer a standardized process-coaching program to eligible facilities. Specify the target trial before opening a regression: eligibility at baseline, one program version, the assignment rule, a common time zero, an outcome window, follow-up and the effect of interest.')+p('An observational emulation must align those elements using existing records. If treated units become eligible only after surviving long enough to enroll, while controls begin follow-up earlier, the comparison embeds time-related selection. A large sample does not correct a mismatched time zero.'),'What is the missing counterfactual for an ATT question?','The recipients’ outcomes over the same follow-up period had those same recipients not received the specified program.'),
    sec('assignment-audit','Reconstruct why facilities received treatment',p('Ask who could enroll, who received an offer, which constraints affected participation, and what managers knew about future outcomes. Keep an audit trail for changes in eligibility, queue position, staff capacity and anticipated need. A binary enrollment field alone cannot answer these questions.')+p('The generator below explicitly makes adoption depend on two baseline characteristics. In a real dataset, the assignment story must come from operational records and domain knowledge. “The program came from headquarters” does not establish exogeneity if headquarters selected sites expected to improve.')),
    sec('dgp','Open the new process-coaching generator',p('Seed 9109 generates 2,400 fictional facilities. Workload X is standard normal; baseline type B is Bernoulli with probability 0.45. The adoption probability follows a logistic rule. Outcomes are an arbitrary performance index, and all noise terms are independently generated.')+eq('P(D=1 | X,B) = expit(−0.3 + 1.2X + 0.8B).')+eq('Y(0) = 45 + 4X + 2X² + 3B + ε, ε ∼ N(0,5²); τ(X,B) = 3 + 1.5X + 2B.')+p('Treatment is conditionally exchangeable given X and B by construction, and every finite X has theoretical overlap. The nonlinear baseline and heterogeneous effects are intentional: a single adjusted slope need not represent every population.')),
    sec('clock','Draw the graph in chronological order',p('Place eligibility, X and B before assignment; place actual program exposure after assignment; place performance and follow-up retention afterward. Variables measured in one database extract may correspond to different causal times. Record the measurement date and the phenomenon’s timing separately.')+dag({'X,B':(360,50),'D':(130,180),'Y':(590,180)},[('X,B','D'),('X,B','Y'),('D','Y')],'Baseline characteristics precede program selection and outcome')+p('A baseline variable can be affected by earlier treatment episodes. If the policy includes repeated treatment, the simple single-period graph may be inadequate; time-varying confounding needs a different design and estimator.')),
    sec('control-causes','Adjust for causes of selection and outcome',p('X and B affect both enrollment and the untreated outcome. Conditioning on them blocks the common-cause routes in the stated generator. A sufficient adjustment set need not include every variable that predicts performance; it must address the relevant noncausal paths.')+p('The squared term X² is not a new causal variable measured after treatment. It is a functional transformation used to model the nonlinear conditional mean. Including X in a graph and including an appropriate functional form in a regression are different tasks.'),'If X is the correct confounder, is a straight-line adjustment always adequate?','No. The identification argument conditions on X; a linear regression approximates that conditional relationship. Nonlinearity or interactions may require a richer model.'),
    sec('bad-controls','Not every useful predictor is a useful control',p('Program attendance, post-enrollment staffing and a final satisfaction score may predict performance. They can also be mediators or consequences of selection and outcome causes. Adjusting for them may block part of the treatment effect or create collider bias.')+p('A measurement’s predictive value is not evidence of causal appropriateness. Decide whether a variable belongs in the design from its timing and causal role, then assess how to represent it statistically. Do not add a post-treatment variable simply because it improves R².')),
    sec('estimand','Choose whose gains the decision concerns',table(['Target','Known generated effect'],[['All facilities: ATE',f(r['truth']['ate'])],['Recipients: ATT',f(r['truth']['att'])],['Nonrecipients: ATU',f(r['truth']['atu'])]],'Heterogeneous effects make the target population consequential')+p('Expanding the program, retaining the current program and offering it to current nonrecipients are distinct decisions. The sample effects differ because adoption is related to characteristics that also modify gains. The same conditional effect function can therefore imply different average benefits.'),'Does a larger ATT imply selection bias in a correctly adjusted ATT estimate?','No. ATT and ATE can truly differ. Bias concerns disagreement between an estimator’s expectation and its own target, not the difference between valid targets.'),
    sec('versions','Audit what the treatment flag actually contains',p('A field called “program participant” could combine a short webinar, intensive coaching and partial attendance. If the policy decision concerns a specific package, a mixture flag may not define a stable intervention. Record treatment version, start date, dose, adherence and co-interventions.')+p('The synthetic D is deliberately a single version. That simplification makes consistency transparent but should not be imported silently into real work. If dose varies because of evolving needs, simply controlling for dose can change the estimand or introduce bias.')),
    sec('sample-rule','A one-character Boolean error changes the population',p('A separate artificial eligibility audit defines facilities aged at least 3 years and located in North or South. The correct rule uses AND between age and allowed region. Replacing it with OR silently admits younger facilities or other regions.')+table(['Rule','Rows retained'],[['Age eligible AND region eligible',audit['correct_n']],['Age eligible OR region eligible',audit['wrong_n']],['Extra rows from wrong rule',audit['extra_n']]],'Synthetic sample-rule audit, separate from the main analysis')+p('Test inclusion logic on hand-checked edge cases before estimating outcomes. Parentheses matter when combining AND/OR. Report a sample-flow table with reasons for every exclusion; do not treat a changed denominator as a cosmetic cleaning detail.'),'Should this eligibility example be silently applied to the main 2,400-facility analysis?','No. It is a separate audit exercise. The main generator’s estimand concerns its full stated population; applying a filter would change that target and require recomputation.'),
    sec('descriptive','Read both group means before explaining the difference',table(['Group','Count','Mean performance'],[['Treated',r['treated'],f(r['means']['treated'])],['Control',r['control'],f(r['means']['control'])]],'Observed outcomes from the synthetic program population')+p(f"The descriptive gap is {f(r['raw_gap'])}. Recipients have a different baseline composition and a different average treatment effect. The gap cannot be assigned wholly to coaching. Report this contrast honestly as an association before presenting any adjustment.")+bars(['Control','Treated'],[r['means']['control'],r['means']['treated']],'Observed outcome means, before adjustment','Performance index')),
    sec('standardization','Regression adjustment is predict, contrast, average',eq('m̂(d,x,b) = β̂₀ + β̂D d + β̂X x + β̂Q x² + β̂B b + β̂DX dx + β̂DB db.')+p('Fit the conditional outcome model on observed outcomes. For every facility, predict once setting D=1 and once setting D=0 while retaining its baseline X and B. Subtract those predictions, then average over the target population. This is regression standardization, also called the g-formula in this setting.')+eq('ATÊ = n⁻¹ Σᵢ {m̂(1,Xᵢ,Bᵢ) − m̂(0,Xᵢ,Bᵢ)}.')+p(f"The fitted standardized ATE is {f(reg['ate'])}; the generated ATE is {f(r['truth']['ate'])}. Agreement here follows from a known adequate adjustment set and correct outcome-model form, plus ordinary sampling error.")),
    sec('interactions','A treatment coefficient is not always an average effect',p(f"The model’s D coefficient is {f(reg['beta'][1])}, the fitted contrast at X=0 and B=0. Its D×X coefficient is {f(reg['beta'][5])}, and D×B coefficient is {f(reg['beta'][6])}. The conditional effect is their sum with the appropriate covariate values.")+eq('τ̂(x,b) = β̂D + β̂DX x + β̂DB b.')+p(f"Averaging over the observed B=0 subgroup yields {f(reg['subgroup_b0'])}; averaging over B=1 yields {f(reg['subgroup_b1'])}. These subgroup averages also reflect differing X composition. To isolate effect modification by B at a common X distribution, standardize both groups to that same X distribution."),'Why is β̂D not the ATE here?','Because effect modifiers enter through interactions. β̂D is a reference-profile effect, while ATE averages the whole conditional effect function over the target covariate distribution.'),
    sec('averaging','Hold the fitted contrasts fixed and change target weights',table(['Averaging population','Standardized estimate','Known truth'],[['All facilities',f(reg['ate']),f(r['truth']['ate'])],['Treated facilities',f(reg['att']),f(r['truth']['att'])],['Untreated facilities',f(reg['atu']),f(r['truth']['atu'])]],'One fitted model, three target populations')+p('To estimate ATT, average counterfactual prediction differences only over recipients. To estimate ATU, average only over nonrecipients. This operation changes the estimand without refitting the outcome model. It is not the same as fitting separate regressions in selected subsets.')+p('Model extrapolation is more consequential for targets concentrated in regions with weak support. Report where each target’s counterfactual predictions come from.')),
    sec('shape','Audit omitted causes, shape and support separately',p(f"An additive model without treatment interactions produces a constant contrast of {f(r['additive']['ate'])}. It can look close to the ATE in this particular draw while failing to represent ATT, ATU or subgroup effects. Numerical closeness is not proof that its structural restriction is appropriate.")+p('Three failures should not be conflated: an omitted common cause threatens identification; the wrong conditional mean form threatens estimation; and weak overlap forces extrapolation. A larger model may help functional form but cannot manufacture the absent treatment alternative or measure an omitted cause.')),
    sec('hidden-confounding','A separate hidden-cause experiment tests a real vulnerability',p('The lab next draws a new latent U that raises both treatment propensity and outcome, then fits a model that omits it. The treatment effect in this separate DGP is constant at 3. X and B are still adjusted for, but they no longer make treatment ignorable.')+p(f"The resulting adjusted treatment coefficient is {f(h['adjusted_omitting_u'])}, compared with the known {f(h['true_effect'])}. This is not a correction to the original estimate. It demonstrates a failure mode under changed causal assumptions.")+p('A real sensitivity analysis should quantify plausible omitted-cause strength using domain knowledge, negative controls or validation data. Do not label an arbitrary alternate DGP as an empirical bound.'),'Why can several adjustment methods agree yet all be biased?','They may rely on the same incomplete covariate set. Agreement across estimators does not test the shared no-unmeasured-confounding assumption.'),
    sec('overlap','Show who can actually be compared',line_chart(scores['hist_centers'],{'Control':scores['control_hist'],'Treated':scores['treated_hist']},'Estimated propensity-score distribution','Bin midpoint; bins have width 0.1','Facilities per bin')+p(f"Estimated scores range from {f(scores['min'])} to {f(scores['max'])}; {scores['tail_n']} facilities have scores below 0.05 or above 0.95. The line joins histogram-bin counts for readability; it is not a probability density or a trajectory.")+p('Inspect covariate combinations as well as the one-dimensional score. Two fitted scores can look similar despite important covariate imbalance when the propensity model is misspecified. Histograms diagnose available support; they do not certify exchangeability.')),
    sec('positivity','A model cannot create an untreated comparison',p(f"In a separate deterministic rule D=1 if X>0.5, {r['hard_assignment_treated_without_controls']} facilities are treated in a region with no untreated facilities. A fitted regression can still output predictions there, but causal identification no longer comes from within-region comparisons.")+p('Possible responses include narrowing the target to common support when any exists, collecting new comparisons, changing the design or explicitly invoking extrapolation assumptions. In this deterministic example no covariate value has both treatments, so trimming alone cannot repair the design. A regression-discontinuity argument near the cutoff would require its own continuity assumptions and identify a local target. Any trimming changes the population and must be reported.'),'Does a fitted logistic score strictly between zero and one prove positivity?','No. A smooth model can output interior probabilities even when the true assignment mechanism deterministically rules out one treatment in part of the covariate space.'),
    sec('balance','Measure balance under the weights actually used',table(['Covariate','Unweighted SMD','IPW SMD','CEM SMD'],[[v['variable'],f(v['before']),f(v['ipw']),f(v['cem'])] for v in r['balance']],'Signed standardized mean differences; denominator held fixed')+eq('SMD = (weighted mean treated − weighted mean control) / unweighted pooled within-arm SD.')+p('The fixed denominator makes before/after changes interpretable as changes in mean imbalance, not changes in the scaling rule. Examine absolute magnitudes for balance, but retain signs to understand direction. The table includes X² because mean balance in X need not balance nonlinear functions.')+p('A threshold such as 0.1 is a heuristic, not a theorem of causal validity. Inspect distributions, interactions and substantively important covariates, not only an average balance score.')),
    sec('cem','Coarsened exact matching makes a tradeoff explicit',p('The lab divides X at −1.5, −0.75, 0, 0.75 and 1.5, then crosses those bins with B. A cell is retained only if it contains both treatments. This is exact matching on coarsened variables, not exact matching on the original continuous X.')+table(['Cell code','Treated','Control','Retained'],[[v['cell'],v['treated'],v['control'],'Yes' if v['retained'] else 'No'] for v in r['cells']],'CEM cells: code equals 2 × workload-bin index + B')+p('Narrower bins can improve within-cell comparability but discard more units. Wider bins retain support at the cost of residual differences. Predeclare substantively meaningful cutpoints when possible, and examine sensitivity to reasonable alternatives without picking the most favorable outcome.')),
    sec('cem-target','Matching weights preserve a stated target',eq('ATT CEM weights: treated weight = 1; control weight in cell s = n₁ₛ / n₀ₛ.')+p(f"The retained sample contains {r['cem_kept_treated']} treated and {r['cem_kept_control']} control facilities. The CEM ATT estimate is {f(r['cem'])}; the known effect for retained recipients is {f(r['cem_truth_att'])}. Coarse X bins can leave residual confounding even when every cell has both groups.")+p('Each retained cell’s control total weight equals its treated count, reproducing the retained-treated cell distribution. If some treated cells were dropped, this would target retained recipients, not every original recipient. Keep the retained-population label beside the estimate.')),
    sec('propensity','A score organizes comparisons, not causal knowledge',eq('e(X,B) = P(D=1 | X,B).')+p('The propensity score balances measured covariates in the population when correctly specified. Under conditional exchangeability and overlap, it can support matching, subclassification or weighting. Here a logistic model with X and B matches the generator’s assignment form.')+p('A high classification accuracy is not the goal. Near-perfect treatment prediction can signal poor overlap and extreme weights. Select variables using the causal question and evaluate covariate balance after adjustment. A score cannot balance an unrecorded cause merely by summarizing recorded variables.'),'Why not tune the model only for the best AUC?','AUC measures treatment discrimination, not the quality of the causal comparison. The design needs balance, support and a credible measured-confounder set.'),
    sec('ipw','Weights reveal the cost of rare comparisons',eq('ATE weights: D/ê(X,B) + (1−D)/(1−ê(X,B)); Hájek estimator normalizes weights separately within each arm.')+p(f"The normalized inverse-probability weighted ATE is {f(r['ipw'])}. The largest individual weight is {f(w['max'])}; effective sample sizes are {f(w['ess_t'],1)} treated and {f(w['ess_c'],1)} control, compared with raw counts {r['treated']} and {r['control']}.")+eq('ESS = (Σᵢ wᵢ)² / Σᵢ wᵢ².')+p('ESS is a useful weight-concentration diagnostic, not a universal replacement for sample size in every standard-error formula. Truncating weights trades variance against bias and potentially changes the effective target. Report both the rule and its consequences.')),
    sec('method-comparison','Compare like targets before comparing methods',table(['Method','Target','Estimate','Corresponding generated truth'],[['Raw mean gap','Descriptive',f(r['raw_gap']),'Not a causal estimand'],['Regression standardization','ATE',f(reg['ate']),f(r['truth']['ate'])],['Normalized IPW','ATE',f(r['ipw']),f(r['truth']['ate'])],['Regression standardized to recipients','ATT',f(reg['att']),f(r['truth']['att'])],['CEM','Retained ATT',f(r['cem']),f(r['cem_truth_att'])]],'Estimates and their distinct targets')+p('Different values may reflect distinct estimands, model approximations, residual within-cell imbalance or finite-sample variability. A robustness table should explain those differences. Counting how many estimates are positive ignores both their dependence and their identifying assumptions.')),
    sec('uncertainty','Attach uncertainty to the actual estimator',p(f"For regression standardization, the lab computes an HC3 heteroskedasticity-robust covariance matrix and applies the linear-combination variance formula to the sample-average prediction contrast. The ATE estimate {f(reg['ate'])} has robust SE {f(reg['ate_se'])} and an approximate 95% interval [{f(reg['ate_low'])}, {f(reg['ate_high'])}].")+eq('Var(τ̂) = L̄ᵀ Var(β̂) L̄, where L̄ averages the design-vector contrast under D=1 versus D=0.')+p('This interval conditions on the observed target covariates and assumes independent facilities and a correct conditional mean. A superpopulation target adds covariate-sampling uncertainty. IPW and CEM need their own inference accounting for fitted weights, matching and clustering; this regression interval should not be reused for them.'),'Does the robust interval include uncertainty about unmeasured confounding?','No. “Robust” here describes protection against heteroskedastic errors, not robustness to a wrong causal graph, lack of overlap or unmeasured causes.'),
    sec('validity','Internal validity and transport ask different questions',p('Internal validity concerns whether the comparison identifies the effect for the study population. External validity concerns whether that effect applies to another population, implementation or time. A representative sample does not fix confounding, and a well-randomized trial need not represent the policy target.')+p('Keep four populations separate: eligible units, observed units, units retained after support restrictions, and units affected by the proposed decision. Selection between these populations can depend on effect modifiers. Transporting an average requires assumptions about how those effects and intervention versions carry over.')),
    sec('transport','Transport the effect function, not the raw average',p('A new hypothetical target is generated with X ∼ N(0.7,1) and P(B=1)=0.7. The structural effect function is held fixed solely for this exercise. Standardizing the fitted conditional effects over the target covariates estimates the target average.')+table(['Population','Estimated effect','Generated truth'],[['Original facilities',f(reg['ate']),f(r['truth']['ate'])],['Different target facilities',f(r['transport']['estimated_target']),f(r['transport']['true_target'])]],'Transport under an explicit effect-invariance assumption')+p('This calculation requires conditional effect transportability and adequate support for target covariates, along with a consistent intervention. The synthetic generator supplies those assumptions; observed source data alone would not prove them.')),
    sec('reproduction','Reproduction should expose decisions, not just rerun code',p('The downloadable notebook contains the exact standalone generator and fresh output. It reads no external files and uses no network. Inspect the assignment equation, eligibility exercise, treatment interactions, CEM boundaries, score model, weight normalization and covariance calculation.')+p('A useful reproduction records the estimand before and after exclusions, the unit of analysis, sample counts, seeds, dependencies and model formulas. Test that each reported value comes from the saved analysis rather than a copied number. Changing a seed examines simulation variability; changing a causal assumption examines a different world.'),'Which changes require recomputing more than the final coefficient?','Changes to eligibility, treatment definition, target, bin boundaries or weights can alter counts, balance, support, estimands and uncertainty. Rebuild the full evidence chain.'),
    sec('bounded-brief','Say what the evidence supports and what comes next',p(f"In this fictional population, the correctly specified standardized ATE is {f(reg['ate'])}, with a generated target of {f(r['truth']['ate'])}. The difference from the descriptive gap illustrates selection and heterogeneity. Matching and weighting provide complementary diagnostics, not independent proofs of causality.")+p('For a real program decision, recommend the next evidence that attacks the weakest assumption: better assignment records, a baseline common cause, stronger overlap, a randomized offer or a transport sample. State what remains an association and what would justify a causal claim. Do not convert a synthetic success into a factual claim about real facilities.'),'What makes an observational recommendation appropriately bounded?','It names the decision, target, assumptions, support and uncertainty, distinguishes causal from descriptive claims, and specifies the evidence that could materially change the recommendation.')
    ]
    assert len(sections)==28
    render_lesson(9,'Audit the adjusted comparison','Connect target-trial design to regression standardization, matching, propensity diagnostics and credible population claims.',sections)
    return sections

def lesson10(r):
    a=r['means'];v=r['violations'];pre=r['pretrend'];s=r['sensitivity']
    sections=[
    sec('decision','Begin with the rollout decision, not a regression',p('A fictional service network introduces a scheduling protocol at selected facilities. Performance rises afterward. The decision is whether that increase reflects the protocol or changes that would have happened anyway. A before–after contrast is not enough, and a post-period comparison can retain persistent differences between facilities.')+p('Difference-in-differences combines the two comparisons. It uses a comparison group’s change to estimate the untreated change for adopters, under a parallel-trends argument. Its attraction is not that it controls for everything, but that stable level differences need not invalidate the design.'),'What does DiD ask the comparison group to provide?','The change adopters would have experienced without treatment, not necessarily the adopters’ baseline outcome level.'),
    sec('generator','Inspect the synthetic panel before estimating it',p('Seed 10110 generates 80 fictional facilities over eight periods. Adoption is selected using baseline type X plus independent noise. Baseline performance depends on X, creating a persistent level difference. All adopters begin at period 4; there is no staggered adoption in this main example.')+eq('Yᵢₜ(0) = αᵢ + λₜ + uᵢₜ; uᵢₜ = 0.65uᵢ,ₜ₋₁ + ηᵢₜ; Yᵢₜ = Yᵢₜ(0) + Gᵢ 1(t≥4)τᵢ.')+eq('αᵢ = 55 + 5Xᵢ + baseline noise; τᵢ = 2 + 1.2Xᵢ.')+p('The common period effects are invented inputs, and serially correlated noise makes repeated observations dependent. Expected untreated trends are parallel because the same λ applies to both groups and noise is generated independently of adoption. Realized sample untreated changes can still differ by chance.')),
    sec('missing-outcome','The missing outcome is adopters without rollout',p('For the treated group in the post period, observe Y(1) but not Y(0). The comparison group’s post outcome is observed under no rollout, but it is not directly the treated group’s counterfactual level. DiD transports a change, not a level.')+eq('ATTpost = E[Ypost(1) − Ypost(0) | G=1].')+p('The lab displays untreated potential outcomes only because it generated them. In an actual rollout those trajectories would be unavailable; no plotting command could reveal them. The identification argument supplies a counterfactual mean under stated assumptions.')),
    sec('target','An adopter effect is not an effect for every facility',p(f"The generated average post-rollout effect among adopters is {f(r['truth_att'])} index points. Because effect size varies with X and adoption is selected, this need not equal the effect for nonadopters or the entire network.")+p('The main estimator gives equal weight to each facility and averages four pre and four post periods. Changing facility weights or the time window changes the average being estimated. Name the units, recipients and periods next to any reported ATT.'),'Would this design identify gains from universal rollout?','Not without assumptions about effects for current nonadopters and the consequences of wider adoption, including potential spillovers and implementation changes.'),
    sec('two-by-two','Make the two-by-two layout visible',table(['Group','Pre-period mean','Post-period mean','Facilities'],[['Comparison',f(a['control_pre']),f(a['control_post']),r['control_units']],['Treated',f(a['treated_pre']),f(a['treated_post']),r['treated_units']]],'Equal-facility averages; periods 0–3 pre and 4–7 post')+p('The cells are averages of the same facilities across the same periods. No facility changes its design group after baseline, and none disappears. These features are assumptions of the constructed case, not properties to take for granted in administrative data.')),
    sec('first-differences','First difference: measure each group’s movement',eq('Δtreated = Ȳtreated,post − Ȳtreated,pre; Δcontrol = Ȳcontrol,post − Ȳcontrol,pre.')+p(f"Treated facilities improve by {f(r['treated_change'])} points; comparison facilities improve by {f(r['control_change'])}. The treated before–after increase combines treatment and untreated movement. The comparison increase estimates the latter only under the design assumptions.")+bars(['Comparison change','Treated change'],[r['control_change'],r['treated_change']],'The two within-group changes','Performance-index points'),'Why can a positive treated-group change coexist with a negative treatment effect?','If the untreated change would have been even larger, treatment can reduce the outcome relative to that counterfactual while the observed outcome still rises.'),
    sec('second-difference','Second difference: subtract the comparison trend',eq('DiD = (ȲT,post − ȲT,pre) − (ȲC,post − ȲC,pre).')+p(f"Here DiD = {f(r['treated_change'])} − {f(r['control_change'])} = {f(r['did'])} points. Algebraically, this also equals the post-period treated–control gap minus the pre-period gap. Both forms should agree exactly in the reproduced output.")+p('Subtracting removes a persistent baseline difference. It does not remove a new group-specific shock, differential trends or changes in who appears in each group. The design’s credibility rests on those distinctions, not on subtraction itself.')),
    sec('counterfactual','Construct the treated group’s counterfactual trend',eq('Predicted untreated treated-post mean = ȲT,pre + (ȲC,post − ȲC,pre).')+p(f"That counterfactual is {f(r['counterfactual'])}; the treated observed post mean is {f(a['treated_post'])}. Their difference is {f(r['did'])}. The full trajectory plot also shows the generator’s otherwise unobservable treated-untreated truth, so you can see the role of sampling noise.")+line_chart(list(range(r['periods'])),r['series'],'A synthetic rollout and its known counterfactual','Period; rollout starts at 4','Mean performance index'),'Why is the synthetic truth line not identical to the comparison-shifted counterfactual in every period?','Parallel expected untreated trends do not force realized sample noise to cancel exactly. DiD remains subject to sampling variability even when the generator satisfies identification assumptions.'),
    sec('scale','A change in levels is not a proportional change',p('Parallel trends in levels and parallel trends in logs are different assumptions. An additive common shock can be parallel in levels but not proportional across groups with different baselines. Choose an outcome scale based on the mechanism and decision, not which specification produces a more favorable estimate.')+p('A percentage change divides by a baseline; a percentage-point change subtracts rates. When the outcome is a monetary or production level, DiD is in those units. When it is a probability expressed as a percent, a level DiD is in percentage points.'),'Does a larger treated baseline invalidate level DiD?','No. Stable level differences are allowed. What matters is the untreated change assumption on the chosen scale.'),
    sec('parallel','Parallel trends concerns unobserved untreated outcomes',eq('E[Ypost(0) − Ypre(0) | G=1] = E[Ypost(0) − Ypre(0) | G=0].')+p('This is not a claim that observed outcomes remain parallel after treatment. A successful intervention should separate the observed trajectories. Nor does it require equal baseline levels. It is a restriction on the untreated counterfactual change over the analysis window.')+p('Defend it using the intervention’s assignment process, exposure to common shocks, prior dynamics, institutions and measurement stability. A comparison group chosen only because its pre-period line looks convenient can introduce design selection and conceal substantive differences.')),
    sec('drift','Quantify the consequence of a differential untreated trend',eq('Observed DiD = ATT + δ, where δ is the treated-minus-control untreated change.')+p(f"A separate variant adds an untreated drift of 0.35 points per period only to treated facilities. The difference between mean post and pre period indices is four, so the added bias is {f(v['drift_bias'])}. The estimated DiD becomes {f(v['differential_drift'])}, although treatment effects are unchanged.")+line_chart(s['drifts'],{'Bias-adjusted effect':s['effects']},'Sensitivity to a specified untreated-change difference','Assumed δ across the analysis window','Adjusted effect in index points')+p('The sensitivity graph subtracts candidate δ values from the original estimate. These are assumptions, not confidence bounds or estimates of actual bias. Calibrate them using substantive evidence before using them for a decision.')),
    sec('anticipation','The treatment can begin before its official date',p(f"Another variant adds an anticipatory effect of 1.2 points to adopters in period 3. Because period 3 is included in the four-period baseline, the DiD estimate falls to {f(v['anticipation'])}. The contaminated baseline absorbs part of the effect.")+p('Announcement, preparation, stockpiling and strategic timing can change behavior before official rollout. Define the first date behavior could respond, examine early exposure and choose comparison windows accordingly. Dropping a suspicious pre-period after seeing results changes the design and must be reported.'),'Can flat earlier pre-periods rule out anticipation immediately before rollout?','No. Anticipation can begin after the earlier data end. Chronology and implementation records are needed alongside outcome plots.'),
    sec('spillovers','The comparison group must remain a meaningful alternative',p(f"A spillover variant gives comparison facilities a post-period improvement of 0.8 points from shared practices. The estimated contrast becomes {f(v['comparison_spillover'])}. It now measures the difference between direct exposure and the spillover regime rather than treatment versus no exposure.")+p('Network spillovers can also worsen comparison outcomes through displacement. The direction of bias is not universally toward zero. Define the exposure mapping and interference boundary, and consider cluster or network designs when implementation spreads across units.')),
    sec('composition','Changing participants can mimic a treatment effect',p(f"In a composition variant, only the higher-baseline half of treated facilities remains in post-period observations. The observed treated count falls to {v['post_treated_retained']}, and the naive DiD rises to {f(v['composition'])}. The treatment mechanism has not changed; the observed population has.")+p('A balanced panel protects against this particular mechanical change but may select a special survivor population. Repeated cross-sections can support DiD if sampling and composition assumptions are appropriate. Track entry, exit, missing outcomes and the reasons for exclusion rather than treating all missing rows as interchangeable.'),'Is restricting to complete panels automatically unbiased?','No. If survival or reporting depends on treatment and outcome causes, complete-panel selection can induce bias. The resulting target also excludes units that disappeared.'),
    sec('pretrends','Pre-trend evidence can challenge but not certify the design',p(f"The placebo change from period 0 to 3 differs by {f(pre['difference'])} points between groups. Its Welch SE is {f(pre['se'])}, with {f(pre['df'],1)} degrees of freedom, and approximate 95% interval [{f(pre['low'])}, {f(pre['high'])}]. The two-sided p-value is {f(pre['p_value'])}.")+p('A nonsignificant test does not prove equality, especially with few pre-periods or noisy outcomes. A significant difference can challenge the design, but its practical magnitude and likely continuation matter. Passing a test after searching many controls or windows is not independent validation.')+p('Pre-period patterns cannot rule out a post-period group-specific shock. Use them as one part of the argument and describe the size of deviations the data could still permit.')),
    sec('interaction','The interaction regression reproduces the same contrast',eq('Yᵢₜ = α + γGᵢ + λPostₜ + β(Gᵢ × Postₜ) + εᵢₜ.')+table(['Term','Fitted coefficient','Meaning'],[['Intercept',f(r['regression_beta'][0]),'Comparison pre mean'],['Treated group',f(r['regression_beta'][1]),'Baseline group gap'],['Post',f(r['regression_beta'][2]),'Comparison-group change'],['Group × post',f(r['regression_beta'][3]),'Difference-in-differences']],'Saturated two-by-two regression, using all unit-period rows')+p('With the same weights and windows, the interaction coefficient equals the table calculation. Regressing unit-level post-minus-pre changes on a treatment indicator gives the same point estimate. Algebraic equivalence is not an additional identification argument.')),
    sec('weights','An average effect needs an explicit weighting rule',p(f"Equal-facility DiD is {f(r['did'])}. Weighting by fixed baseline exposure counts yields {f(r['weighted_did'])}. The corresponding generated recipient effects are {f(r['truth_att'])} and {f(r['weighted_truth_att'])}. Both are legitimate descriptive targets under their stated weights, but they answer different policy questions.")+p('Equal-unit weights emphasize the typical facility. Exposure weights emphasize the typical baseline exposure. Use predetermined weights when possible; contemporaneous activity can itself respond to treatment, changing the population represented by a weighted estimate.')+eq('Weighted ATT = Σᵢ:Gᵢ=1 wᵢτᵢ / Σᵢ:Gᵢ=1 wᵢ.'),'Is an exposure-weighted estimate automatically more accurate?','It may be more relevant for an exposure-level decision, but it changes the estimand. Accuracy and relevance must be assessed for that target, not judged by which number is larger.'),
    sec('cluster','Repeated rows are not independent assignment units',p(f"There are {r['rows']} unit-period rows but only {r['units']} facilities. The regression’s ordinary independent-row SE is {f(r['naive_se'])}; its facility-clustered CR1 SE is {f(r['cluster_se'])}. A t interval with {r['units']-1} degrees of freedom is [{f(r['interval'][0])}, {f(r['interval'][1])}].")+p('Here clustering makes the standard error smaller, not larger: persistent facility levels contribute to ordinary residual variance but cancel in before–after contrasts. The general rule is to match the dependence structure, not to assume that every clustered SE must inflate. The lab explicitly computes the sandwich covariance by summing facility scores.')+p('If assignment occurs at a region level, cluster at the relevant assignment or shock level instead. With very few clusters, conventional cluster-robust approximations may be unreliable; design-based inference, small-sample corrections or an appropriate wild-cluster procedure may be needed.')),
    sec('conditional','Conditional DiD needs its own comparability argument',eq('E[ΔY(0) | G=1,X] = E[ΔY(0) | G=0,X], plus overlap in G given X.')+p('If untreated trends differ with baseline X, comparing changes within X can be more plausible than unconditional parallel trends. Standardize those conditional changes to the treated population, rather than assuming any regression containing X identifies the desired ATT.')+p('Use baseline covariates, not variables altered by treatment. If covariates themselves evolve because of rollout, controlling for their post values can block mechanisms or induce selection. A model with time-varying controls requires a correspondingly explicit causal question.')),
    sec('chronology','The chronology determines the analysis window',p('The synthetic panel has periods 0–3 untreated and periods 4–7 exposed for adopters. All comparison facilities remain unexposed in the main DGP. Write the timeline before selecting windows: announcement, preparation, start, uptake, full implementation and follow-up may be distinct dates.')+p('A short post window can measure transition costs; a later window can measure sustained effects. Combining both estimates a time-weighted average. State whether the policy question concerns immediate disruption, steady-state gains or cumulative outcomes, and make the observation window serve that question.')),
    sec('ratios','Aggregate compatible totals rather than averaging arbitrary ratios',p('Suppose each facility’s performance index is represented as service points per exposure, and baseline exposure counts are the weights. The network rate is total service points divided by total exposures, equivalent to an exposure-weighted mean of facility rates. It is not generally the unweighted mean.')+eq('Network rate = Σᵢ (rateᵢ × exposureᵢ) / Σᵢ exposureᵢ.')+p(f"The synthetic baseline exposure-weighted rate is {f(r['baseline_weighted_rate'])}, compared with the equal-facility mean {f(r['baseline_unweighted_rate'])}. The choice should follow the question. Align numerator and denominator in period, geography, coverage and units before calculating any aggregate."),'Why can averaging quarterly ratios differ from the annual ratio?','Quarterly denominators may differ. The annual ratio requires summed compatible numerators divided by summed denominators, equivalent to denominator-weighted quarterly ratios.'),
    sec('frozen-labels','Freeze design labels at baseline',p('In the main panel, treated group membership, baseline exposure and eligibility are defined before rollout and stay fixed. A facility does not change groups because its post-period outcome or market share changes. Relabeling using post-treatment behavior can turn an outcome of treatment into a selection rule.')+p('Keep separate fields for original assignment, actual exposure and observation status. An intention-to-treat analysis follows original assignment, while an exposure-response analysis asks a different question. Do not overwrite the original design field during data cleaning.')),
    sec('denominators','Audit the row count and the unit count separately',table(['Audit quantity','Count'],[['Facilities',r['units']],['Adopting facilities',r['treated_units']],['Comparison facilities',r['control_units']],['Periods per facility',r['periods']],['Unit-period rows',r['rows']]],'Main balanced-panel design audit')+p('Assert one row per facility-period, stable identifiers, complete windows and consistent treatment labels. Reconcile duplicates, missing cells and aggregation before fitting a model. The notebook asserts the equivalence of the table, interaction coefficient and first-difference calculation.')+p('A report should distinguish raw rows, independent units, treated units, comparison units and excluded units. These denominators answer different questions about coverage and information.')),
    sec('logs','Subtract log changes before translating them',p(f"Applying the same contrast to log outcomes gives {f(r['log_did'],5)}. Exponentiating yields {f(r['log_percent'],3)}%, a differential multiplicative change expressed through ratios of geometric means. This is not a percentage-point effect and is not simply the level DiD divided by one chosen baseline.")+eq('Percent multiplicative contrast = 100 × {exp(βlog) − 1}.')+p(f"Logging each facility’s period-average outcome first instead gives {f(r['log_of_period_means_did'],5)}. Averaging and logging do not commute. The main generator satisfies additive parallel expected trends, not automatically parallel log trends, so this log result is a different specification with an additional identification question.")),
    sec('intensity','A binary rollout flag and an exposure slope ask different questions',p('If facilities receive different planned training hours, a binary ever-treated contrast does not identify the gain from one additional hour. A dose-response slope requires a defined exposure, sufficient support across doses and an assumption about untreated changes conditional on dose and confounders.')+p('The main lab deliberately avoids fitting an intensity slope because its generated intervention is binary. Creating a continuous exposure from post-rollout activity would change the treatment definition and can create reverse causality. If dose is endogenous, name that limitation rather than interpreting a convenient regression slope causally.'),'Can a good binary DiD design automatically identify the causal dose-response curve?','No. Dose selection can follow a different mechanism, and a one-unit dose effect requires additional structural, support and trend assumptions.'),
    sec('heterogeneity','Heterogeneous effects complicate aggregation and staggered adoption',table(['Recipient subgroup','Facilities','Known generated average effect'],[[v['type'],v['n'],f(v['true_att'])] for v in r['subgroups']],'Synthetic recipient heterogeneity; these are generator truths, not subgroup estimates')+p('The main example has one adoption date and no treatment reversal. With staggered adoption, a two-way fixed-effects regression can use already-treated units as controls and combine cohort-time effects with problematic weights when effects vary over time or cohorts.')+p('Define cohort-time ATT targets, choose valid not-yet-treated or never-treated comparisons, state no-anticipation assumptions and aggregate with transparent weights. Do not treat the simple two-by-two algebra as a blanket justification for every panel regression.')),
    sec('decision-audit','A narrow interval does not remove design uncertainty',p('Separate sampling uncertainty from uncertainty about untreated trends, spillovers, timing and composition. The clustered interval is conditional on the design assumptions. The drift, anticipation, spillover and attrition variants show how changing those assumptions changes the estimated contrast without changing the core treatment mechanism.')+p('For a decision, compare the effect and plausible design deviations with a prespecified practical threshold, rollout cost and risk. Seek evidence aimed at the most consequential vulnerability: implementation dates, neighboring exposures, retention reasons or a better comparison group. Avoid inventing a mechanism from a single interaction coefficient.'),'Which result is more useful: a precise DiD alone or a wider estimate with a defensible comparison story?','Precision is useful only relative to a credible target. Report both design credibility and sampling uncertainty; neither substitutes for the other.'),
    sec('brief','Write a claim another analyst can reconstruct',p(f"The equal-facility synthetic DiD is {f(r['did'])} index points, with a facility-clustered approximate 95% interval [{f(r['interval'][0])}, {f(r['interval'][1])}]. The generated adopter effect is {f(r['truth_att'])}. Their small difference reflects the finite realization of untreated noise, not access to a real counterfactual.")+p('A complete brief supplies the population and timing, comparison selection, frozen design labels, outcome scale, sample-flow counts, weighting rule, parallel-trends argument, uncertainty unit and sensitivity checks. It distinguishes adopter effects from universal-policy effects and states what evidence would change the recommendation.')+p('This course’s data are wholly synthetic. Reuse the code and reasoning to build a transparent workflow, but do not reuse its numerical effects as evidence about real organizations, markets or interventions.'),'What is the central DiD claim you must be able to defend?','Without treatment, the treated group’s relevant average outcome change would have matched the chosen comparison change, on the chosen scale and for the stated population and window.')
    ]
    assert len(sections)==28
    render_lesson(10,'Difference-in-differences and design threats','Build a counterfactual trend, estimate the rollout contrast, and test how timing, spillovers, weights and selection change the claim.',sections)
    return sections


def main():
    descriptions={
        7:'Original fixed-seed potential-outcome population, exhaustive randomization, encouragement and user-level advertising experiment. All probabilities, effects and cost inputs are invented teaching assumptions.',
        8:'Original fixed-seed strata, nearest-neighbor matching, and independent structural simulations for confounding, collider adjustment and mediation. Each equation is explicit and no external input is used.',
        9:'Original fixed-seed program-selection population with nonlinear baseline, heterogeneous effects, standardization, CEM, propensity weighting, balance, eligibility audit and transport exercise.',
        10:'Original fixed-seed facility panel with a common adoption date, serially correlated noise, clustered DiD inference, pretrend diagnostics and explicit alternative DGPs for design threats.'}
    for n,script,build in [(7,LAB7,lesson7),(8,LAB8,lesson8),(9,LAB9,lesson9),(10,LAB10,lesson10)]:
        result=write_lab(n,script,descriptions[n]);sections=build(result)
        # Compact public source map, with no historical case payloads.
        (ROOT/'content'/f'lesson{n}-synthetic-map.json').write_text(json.dumps({'lesson':n,'seed':result['seed'],'provenance':descriptions[n],'sections':[{'id':s['id'],'title':s['title']} for s in sections]},indent=2)+'\n')
        (ROOT/'content'/f'lesson{n}-outline.json').write_text(json.dumps([s['title'] for s in sections],indent=2)+'\n')
        print(f'Built lesson {n}: {len(sections)} original stops; seed {result["seed"]}')

if __name__=='__main__':main()
